const app=document.querySelector('#app');
const questions=['Любимые фильмы или сериалы','Любимые книги','Любимая музыка: исполнители или жанры','Любимые занятия и хобби','Любимые города и страны','Какие вещи, бренды, цвета, еда или предметы тебе особенно нравятся?','Что тебе нравится делать на работе','Люди, за которыми тебе интересно следить','Что ещё ты любишь?'];
const examples=['Шрек 2, Наследники, Сумерки','Гарри Поттер, Сто лет одиночества, Дневник Бриджит Джонс','Земфира, Lana Del Rey, техно','бег, керамика, сноуборд, танцы на кухне','Лиссабон, Италия, Япония','красный, винтажные зеркала, Prada, матча, кожаные куртки','Можно добавить свой вариант','Рианна, Стив Джобс, моя бабушка','Всё, что не влезло выше. Можно списком.'];
const areas=['films','books','music','hobbies','places','objects','work','people','other'];
const workTags=['придумывать новое','разбираться','наводить порядок','строить систему','убеждать','работать с людьми','руководить','выступать','делать красиво','решать сложное','начинать с нуля','улучшать существующее'];
let screen='landing',answers=Array(9).fill(''),tags=new Set(),result=null,isDemo=false,busy=false;
const demo={main_insight:'Тебя снова и снова цепляют ситуации, где нельзя действовать раньше времени. У Хичкока, в боксе и в переговорах напряжение не мешает — оно делает выбор точного момента особенно интересным.',key_fragment:'выбор точного момента',main_evidence:[{item:'Хичкок',area:'films',reason:'Зритель знает об опасности раньше героя и ждёт момента, когда знание превратится в действие.'},{item:'Бокс',area:'hobbies',reason:'Противник отвечает на каждый жест: важно дождаться открытия, а не просто ударить сильнее.'},{item:'Переговоры',area:'work',reason:'Реплика меняет ситуацию, поэтому её момент зависит от того, что сказал и сделал другой человек.'}],patterns:[{title:'Не спешить с развязкой',description:'Интерес держится, пока напряжение ещё не разрешилось. Хичкок заставляет ждать, бокс — выжидать открытие, а переговоры — услышать то, после чего можно ответить точно.',evidence:[{item:'Хичкок',area:'films',reason:'Саспенс продлевает ожидание опасного события вместо немедленной развязки.'},{item:'Бокс',area:'hobbies',reason:'Выжидание и финты помогают создать момент для удара.'},{item:'Переговоры',area:'work',reason:'Пауза и вопрос могут изменить следующий ход разговора.'}]},{title:'Ответ меняет следующий ход',description:'В этих вещах нельзя раз и навсегда решить, что делать дальше. В боксе, джазовой импровизации и переговорах каждое действие получает ответ, к которому приходится прислушиваться.',evidence:[{item:'Бокс',area:'hobbies',reason:'Движение соперника меняет дистанцию и доступные действия.'},{item:'Джазовая импровизация',area:'music',reason:'Музыканты подхватывают и меняют друг у друга ритм и музыкальные фразы.'},{item:'Переговоры',area:'work',reason:'Ответ собеседника меняет то, что имеет смысл предложить следующим.'}]}],unexpected_connections:[{item_1:'Хичкок',item_2:'Бокс',area_1:'films',area_2:'hobbies',connection:'У Хичкока напряжение растёт, пока герой не знает об опасности; в боксе финт создаёт похожий разрыв между тем, что видно, и тем, что готовится.'},{item_1:'Джазовая импровизация',item_2:'Переговоры',area_1:'music',area_2:'work',connection:'В обоих заранее приготовленная фраза может оказаться слабее ответа, который появился из внимательного слушания другого.'}]};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function count(){return answers.reduce((n,a)=>n+a.split(/[,;\n]+/).filter(s=>s.trim()).length,0)+tags.size}
function go(s){if(busy)return;screen=s;render();window.scrollTo(0,0);const h=app.querySelector('h1,h2');h?.setAttribute('tabindex','-1');h?.focus({preventScroll:true})}
function badge(){return isDemo?'<div class="demo">Пример результата · не анализ твоих ответов</div>':''}
function step(back,next,label){return `<div class="stepnav"><button class="back" onclick="go('${back}')">Назад</button><button class="primary" onclick="go('${next}')">${label}</button></div>`}
function evidence(items){return items.map(e=>`<details><summary>${esc(e.item)}</summary><p>${esc(e.reason)}</p></details>`).join('')}
function insightMarkup(){const text=result.main_insight,key=result.key_fragment;if(key&&text.includes(key)){const i=text.indexOf(key);return esc(text.slice(0,i))+'<span class="gold-mark">'+esc(key)+'</span>'+esc(text.slice(i+key.length))}return esc(text)}
function areaCount(){return new Set([...result.main_evidence,...result.patterns.flatMap(p=>p.evidence)].map(e=>e.area)).size}
function render(){
 if(screen==='landing'){app.innerHTML=`<section class="landing"><div><div class="eyebrow">То, что связывает любимое</div><h1>Между<br><em>строк</em></h1><p class="subtitle">Напиши, что любишь.<br>Посмотри, что повторяется.</p><button class="primary" onclick="go('form')">Найти связи</button><button class="secondary samplelink" onclick="showDemo()">Посмотреть пример</button></div><aside class="composition"><div class="quote serif">Что общего<br>у Хичкока<br>и бокса?</div><div class="pair-preview"><span>Хичкок</span><span>↔</span><span>Бокс</span></div><p class="preview-explanation">Не всё, что видно, выдаёт следующий ход. Скрытая угроза в фильме и финт на ринге заставляют ждать и читать детали.</p><p class="small">Одна из пар в примере результата.</p></aside></section>`;return}
 if(screen==='form'){app.innerHTML=`<section class="page narrow"><div class="topline"><div class="eyebrow">01 / Твои выборы</div><button class="back" onclick="go('landing')">На главную</button></div><h2>Посмотрим, что повторяется в вещах, которые тебе нравятся.</h2><p class="form-lead serif">Пиши первое, что приходит в голову. Ничего объяснять не нужно.</p><p class="intro">Вопросы можно пропускать. Разделяй названия запятыми или новой строкой.</p><form id="answers-form">${questions.map((q,i)=>`<div class="field"><label for="answer-${i}"><b>${String(i+1).padStart(2,'0')}</b>${q}</label>${i===6?`<div class="tags">${workTags.map((t,k)=>`<button type="button" class="tag" data-tag="${k}" aria-pressed="${tags.has(t)}">${t}</button>`).join('')}</div>`:''}<textarea id="answer-${i}" data-index="${i}" maxlength="4000" placeholder="${examples[i]}">${esc(answers[i])}</textarea></div>`).join('')}<div id="error" class="error" role="alert"></div><div class="form-bottom"><div class="count"><span id="count">${count()}</span> вещей <span class="small">/ минимум 12</span><br><span class="small">Лучше 20–30 из разных сфер</span></div><button type="submit" class="primary">Найти связи</button></div></form></section>`;
 app.querySelectorAll('textarea').forEach(el=>el.oninput=()=>{answers[+el.dataset.index]=el.value;document.querySelector('#count').textContent=count()});app.querySelectorAll('[data-tag]').forEach(el=>el.onclick=()=>{const t=workTags[+el.dataset.tag];tags.has(t)?tags.delete(t):tags.add(t);el.setAttribute('aria-pressed',tags.has(t));document.querySelector('#count').textContent=count()});document.querySelector('#answers-form').onsubmit=e=>{e.preventDefault();analyze()};return}
 if(screen==='loading'){app.innerHTML='<section class="page focus"><div class="loading"></div><div class="eyebrow">Между строк</div><h2>Ищем то,<br><i>что повторяется.</i></h2><p class="intro" style="margin:0 auto">Находим возможные связи.<br>Оставляем те, которые подтверждаются твоими выборами.</p><p class="small">Это может занять одну–две минуты.</p></section>';return}
 if(!result){go('form');return}
 if(screen==='insight'){app.innerHTML=`<section class="page focus">${badge()}<div class="eyebrow">Между строк</div><h2 class="insight">${insightMarkup()}</h2><p class="small">Это повторилось в ${areaCount()} сферах твоих выборов.</p><details class="main-proof"><summary>Почему?</summary><div class="proof-items">${result.main_evidence.map(e=>`<div><strong>${esc(e.item)}</strong><p>${esc(e.reason)}</p></div>`).join('')}</div></details><button class="primary" onclick="go('patterns')">Как это связано</button><button class="back" style="margin-top:20px" onclick="go('form')">Вернуться к ответам</button></section>`;return}
 if(screen==='patterns'){app.innerHTML=`<section class="page">${badge()}<div class="eyebrow">02 / Паттерны</div><h2>Неожиданно рядом.</h2><div class="cards" data-count="${result.patterns.length}">${result.patterns.map((p,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><details class="evidence"><summary>Почему?</summary><div class="proof-items">${evidence(p.evidence)}</div></details></article>`).join('')}</div>${step('insight','pairs','Неожиданные пары')}</section>`;return}
 if(screen==='pairs'){app.innerHTML=`<section class="page">${badge()}<div class="eyebrow">03 / Неожиданные пары</div><h2>Вещи, которые тебе нравятся<br><i>по одной причине.</i></h2>${result.unexpected_connections.map(p=>`<article class="connection"><div class="pair">${esc(p.item_1)} <span>↔</span> ${esc(p.item_2)}</div><p>${esc(p.connection)}</p></article>`).join('')}${step('patterns','share','Собрать карточку')}</section>`;return}
 if(screen==='share'){app.innerHTML=`<section class="page share-wrap"><canvas id="share" width="1080" height="1350" aria-label="Карточка результата"></canvas><div class="share-actions">${badge()}<div class="eyebrow">04 / С собой</div><h2>Сохрани<br><i>между строк.</i></h2><p class="intro">Главная фраза, паттерны и неожиданные пары — в одной карточке.</p><button class="primary" onclick="download()">Скачать карточку</button><button class="secondary" onclick="shareCard()">Поделиться</button><p id="share-status" class="small" role="status"></p><button class="back" onclick="go('pairs')">Назад к результату</button></div></section>`;drawCard();document.fonts.ready.then(()=>{if(screen==='share')drawCard()})}
}
function showDemo(){isDemo=true;result=structuredClone(demo);go('insight')}
async function analyze(){const e=document.querySelector('#error');if(count()<12){e.textContent='Добавь ещё '+(12-count())+' вещей. Разделяй названия запятыми или новой строкой.';return}busy=true;screen='loading';render();window.scrollTo(0,0);try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answers:answers.map((a,i)=>({area:areas[i],items:i===6?[a,...tags].filter(Boolean).join(', '):a}))}),signal:AbortSignal.timeout(180000)});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Не удалось выполнить анализ. Попробуй ещё раз.');if(!body.main_evidence||!body.patterns||!body.unexpected_connections)throw new Error('Не удалось прочитать результат. Попробуй ещё раз.');result=body;isDemo=false;busy=false;go('insight')}catch(err){busy=false;go('form');document.querySelector('#error').textContent=err.name==='TimeoutError'?'Анализ занял слишком много времени. Попробуй ещё раз.':err.message}}
function cardLines(x,text,size,width){x.font=`${size}px ${size>=38?'"Cormorant Garamond",Georgia':'Manrope,Arial'}`;let line='',lines=[];for(const word of text.split(' ')){if(x.measureText(line+word).width>width&&line){lines.push(line.trim());line=word+' '}else line+=word+' '}if(line)lines.push(line.trim());return lines}
function drawCard(){const c=document.querySelector('#share'),x=c.getContext('2d');x.fillStyle='#efe9df';x.fillRect(0,0,1080,1350);x.strokeStyle='#cec5b8';x.strokeRect(52,52,976,1246);x.fillStyle='#782c36';x.font='24px Manrope,Arial';x.fillText('М Е Ж Д У  С Т Р О К',85,120);if(isDemo){x.fillStyle='#777268';x.font='18px Manrope,Arial';x.fillText('ПРИМЕР РЕЗУЛЬТАТА',85,157)}
 let y=225,size=64,lines;do{lines=cardLines(x,result.main_insight,size,905);if(lines.length*size*1.1<=455)break;size-=2}while(size>38);x.fillStyle='#24231f';x.font=`${size}px "Cormorant Garamond",Georgia`;for(const line of lines){x.fillText(line,85,y);y+=size*1.1}const fragment=result.key_fragment,startIndex=result.main_insight.indexOf(fragment),endIndex=startIndex+fragment.length;let offset=0;lines.forEach((line,i)=>{const a=Math.max(startIndex,offset),b=Math.min(endIndex,offset+line.length);if(b>a){x.strokeStyle='#947338';x.lineWidth=3;x.beginPath();const left=85+x.measureText(line.slice(0,a-offset)).width;x.moveTo(left,225+i*size*1.1+10);x.lineTo(left+x.measureText(line.slice(a-offset,b-offset)).width,225+i*size*1.1+10);x.stroke()}offset+=line.length+1});
 y=710;x.strokeStyle='#cec5b8';x.lineWidth=1;x.beginPath();x.moveTo(85,y-45);x.lineTo(995,y-45);x.stroke();let titleSize=32;while(result.patterns.some(p=>cardLines(x,p.title,titleSize,845).length>1)&&titleSize>24)titleSize--;result.patterns.forEach((p,i)=>{x.fillStyle='#782c36';x.font='19px Manrope,Arial';x.fillText('0'+(i+1),85,y);x.fillStyle='#24231f';x.font=`${titleSize}px Manrope,Arial`;x.fillText(p.title,140,y,850);y+=52});y=Math.max(y+35,960);let pairSize=29;while(result.unexpected_connections.reduce((n,p)=>n+cardLines(x,`${p.item_1} ↔ ${p.item_2}`,pairSize,905).length*(pairSize*1.2)+14,0)>235&&pairSize>20)pairSize--;result.unexpected_connections.forEach(p=>{const ls=cardLines(x,`${p.item_1} ↔ ${p.item_2}`,pairSize,905);x.fillStyle='#782c36';x.font=`${pairSize}px Manrope,Arial`;for(const l of ls){x.fillText(l,85,y);y+=pairSize*1.2}y+=14});x.fillStyle='#777268';x.font='22px Manrope,Arial';x.fillText('Что повторяется в моих выборах',85,1240);x.font='18px Manrope,Arial';x.fillText('Между строк · '+location.host,85,1275)}
async function cardBlob(){await document.fonts.ready;drawCard();return new Promise(r=>document.querySelector('#share').toBlob(r,'image/png'))}
async function download(){const blob=await cardBlob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mezhdu-strok.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function shareCard(){const blob=await cardBlob(),file=new File([blob],'mezhdu-strok.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Между строк'});return}await download();document.querySelector('#share-status').textContent='Карточка скачана — её можно отправить в любом приложении.'}catch(e){if(e.name!=='AbortError')document.querySelector('#share-status').textContent='Не удалось поделиться. Попробуй скачать карточку.'}}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'stage_preferences',description:'Заполнить ответы и открыть форму, без запуска анализа.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'string'},minItems:9,maxItems:9}},required:['answers'],additionalProperties:false},execute(input){if(busy)throw new Error('Дождись завершения анализа');if(!Array.isArray(input.answers)||input.answers.length!==9||input.answers.some(v=>typeof v!=='string'||v.length>4000))throw new Error('Нужно девять текстовых ответов');answers=[...input.answers];go('form');return{things_count:count(),screen}},annotations:{readOnlyHint:false,untrustedContentHint:false}})}catch{}}
render();
